function clean(value) {
  return String(value ?? '').trim();
}

function firstText(...values) {
  return values.map(clean).find(Boolean) || '';
}

function normalizeBaseUrl(value) {
  return clean(value).replace(/\/+$/, '');
}

function normalizeMime(value) {
  const mime = clean(value).toLowerCase().split(';')[0];
  if (mime.includes('mpeg') || mime.includes('mp3')) return 'audio/mpeg';
  if (mime.includes('mp4') || mime.includes('m4a')) return 'audio/mp4';
  if (mime.includes('webm')) return 'audio/webm';
  if (mime.includes('wav') || mime.includes('wave')) return 'audio/wav';
  if (mime.includes('flac')) return 'audio/flac';
  if (mime.includes('ogg') || mime.includes('oga') || mime.includes('opus') || mime.includes('ptt')) return 'audio/ogg';
  return 'audio/ogg';
}

function extensionFor(mimeType, fileName) {
  const existing = clean(fileName).toLowerCase().match(/\.([a-z0-9]+)$/)?.[1] || '';
  const allowed = new Set(['flac', 'm4a', 'mp3', 'mp4', 'mpeg', 'mpga', 'oga', 'ogg', 'opus', 'wav', 'webm']);
  if (allowed.has(existing)) return existing === 'opus' ? 'ogg' : existing;

  const mime = normalizeMime(mimeType);
  if (mime.includes('mpeg')) return 'mp3';
  if (mime.includes('mp4')) return 'm4a';
  if (mime.includes('webm')) return 'webm';
  if (mime.includes('wav')) return 'wav';
  if (mime.includes('flac')) return 'flac';
  return 'ogg';
}

function safeFileName(value, mimeType, fallbackId) {
  const ext = extensionFor(mimeType, value);
  const base = clean(value || fallbackId || 'audio')
    .replace(/\.[^.]+$/, '')
    .replace(/[^A-Za-z0-9_-]+/g, '_')
    .replace(/^_+|_+$/g, '') || 'audio';
  return `${base}.${ext}`;
}

function stripDataUrl(value) {
  const raw = clean(value);
  const match = raw.match(/^data:([^;]+);base64,(.+)$/i);
  return match ? { mimeType: match[1], base64: match[2] } : { mimeType: '', base64: raw };
}

function looksLikeBase64(value) {
  const raw = clean(value).replace(/\s+/g, '');
  return raw.length >= 80 && raw.length % 4 === 0 && /^[A-Za-z0-9+/]+={0,2}$/.test(raw);
}

function buildWebhookMessage(webhookData) {
  return {
    key: webhookData.key,
    pushName: webhookData.pushName,
    message: webhookData.message,
    messageType: webhookData.messageType,
    messageTimestamp: webhookData.messageTimestamp,
    source: webhookData.source,
  };
}

async function fetchEvolutionMedia({ baseUrl, apiKey, instance, message }) {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}/chat/getBase64FromMediaMessage/${encodeURIComponent(instance)}`,
    headers: {
      apikey: apiKey,
      'Content-Type': 'application/json',
    },
    body: {
      message,
      convertToMp4: false,
    },
    json: true,
    timeout: 30000,
  });

  if (!response?.base64) {
    throw new Error(`Evolution media endpoint returned no base64: ${JSON.stringify(response).slice(0, 500)}`);
  }

  return response;
}

const items = $input.all();
const output = [];

for (const item of items) {
  const source = item.json || {};
  const webhook = $('Webhook1').first().json || {};
  const body = webhook.body || {};
  const data = body.data || {};
  const message = data.message || {};
  const audio = message.audioMessage || message.pttMessage || {};
  const messageId = data.key?.id || source.external_message_id || 'audio';

  const fallbackJson = {
    ...source,
    audioValid: false,
    audioSource: 'evolution_media_failed',
    data: '',
    mimetype: normalizeMime(audio.mimetype || audio.mimeType),
    path: safeFileName(audio.fileName, audio.mimetype || audio.mimeType, messageId),
    audioText: '[audio recebido, mas a midia nao estava disponivel para transcricao]',
    media_warning: 'audio_media_fetch_failed',
  };

  try {
    const inline = firstText(
      message.base64,
      audio.base64,
      source.base64,
      source.data
    );

    let media;
    if (looksLikeBase64(stripDataUrl(inline).base64)) {
      const parsed = stripDataUrl(inline);
      media = {
        base64: parsed.base64.replace(/\s+/g, ''),
        mimetype: firstText(parsed.mimeType, audio.mimetype, audio.mimeType, 'audio/ogg'),
        fileName: audio.fileName,
        mediaType: 'audioMessage',
        source: 'webhook_base64',
      };
    } else {
      const baseUrl = normalizeBaseUrl(firstText(
        body.server_url,
        source.EVOLUTION_API_URL,
        source.evolution_api_url,
        $vars.EVOLUTION_API_URL,
        $vars.SERVER_URL,
        'https://evo.yzihub.com'
      ));
      const apiKey = firstText(
        body.apikey,
        source.EVOLUTION_API_KEY,
        source.evolution_api_key,
        $vars.EVOLUTION_API_KEY,
        $vars.AUTHENTICATION_API_KEY
      );
      const instance = firstText(
        source.EVOLUTION_INSTANCE,
        source.instance,
        body.instance,
        data.instance,
        'Jurema Brokers'
      );

      if (!baseUrl || !apiKey || !instance) {
        throw new Error('Evolution media fetch is missing baseUrl, apiKey or instance');
      }

      media = await fetchEvolutionMedia.call(this, {
        baseUrl,
        apiKey,
        instance,
        message: buildWebhookMessage(data),
      });
      media.source = 'evolution_getBase64FromMediaMessage';
    }

    const mimeType = normalizeMime(firstText(media.mimetype, audio.mimetype, audio.mimeType, 'audio/ogg'));
    const fileName = safeFileName(firstText(media.fileName, audio.fileName), mimeType, messageId);
    const buffer = Buffer.from(media.base64.replace(/\s+/g, ''), 'base64');

    if (!buffer.length) {
      throw new Error('Evolution media base64 decoded to an empty buffer');
    }

    const binaryAudio = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

    output.push({
      json: {
        ...source,
        audioValid: true,
        audioSource: media.source,
        audio_media_endpoint: media.source === 'evolution_getBase64FromMediaMessage'
          ? '/chat/getBase64FromMediaMessage/{instance}'
          : 'webhook.base64',
        audio_media_type: media.mediaType || 'audioMessage',
        audio_media_size: buffer.length,
        data: '',
        mimetype: mimeType,
        path: fileName,
        media_warning: null,
      },
      binary: {
        ...(item.binary || {}),
        audio: binaryAudio,
      },
    });
  } catch (error) {
    output.push({
      json: {
        ...fallbackJson,
        media_error: error?.message || String(error),
      },
      binary: item.binary,
    });
  }
}

return output;

function clean(value) {
  return String(value ?? '').trim();
}

function detectAudioContainer(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 4) {
    return { compatible: false, ext: 'ogg', mimeType: 'audio/ogg', reason: 'empty_or_unreadable_audio_binary' };
  }

  const ascii4 = buffer.subarray(0, 4).toString('ascii');
  const ascii12 = buffer.subarray(0, 12).toString('ascii');

  if (ascii4 === 'OggS') return { compatible: true, ext: 'ogg', mimeType: 'audio/ogg', reason: null };
  if (ascii4 === 'fLaC') return { compatible: true, ext: 'flac', mimeType: 'audio/flac', reason: null };
  if (ascii4 === 'RIFF' && buffer.subarray(8, 12).toString('ascii') === 'WAVE') {
    return { compatible: true, ext: 'wav', mimeType: 'audio/wav', reason: null };
  }
  if (buffer.subarray(0, 3).toString('ascii') === 'ID3' || (buffer[0] === 0xff && (buffer[1] & 0xe0) === 0xe0)) {
    return { compatible: true, ext: 'mp3', mimeType: 'audio/mpeg', reason: null };
  }
  if (ascii12.includes('ftyp')) return { compatible: true, ext: 'm4a', mimeType: 'audio/mp4', reason: null };
  if (buffer[0] === 0x1a && buffer[1] === 0x45 && buffer[2] === 0xdf && buffer[3] === 0xa3) {
    return { compatible: true, ext: 'webm', mimeType: 'audio/webm', reason: null };
  }

  return {
    compatible: false,
    ext: 'ogg',
    mimeType: 'audio/ogg',
    reason: 'unsupported_audio_container_magic_bytes',
    magic: buffer.subarray(0, 12).toString('hex'),
  };
}

return await Promise.all($input.all().map(async (item, index) => {
  const binary = item.binary || {};
  const audio = binary.audio || {};

  let detection;
  try {
    const buffer = await this.helpers.getBinaryDataBuffer(index, 'audio');
    detection = detectAudioContainer(buffer);
  } catch (error) {
    detection = {
      compatible: false,
      ext: 'ogg',
      mimeType: 'audio/ogg',
      reason: 'audio_binary_read_failed',
      error: error?.message || String(error),
    };
  }

  const baseName = clean(audio.fileName || item.json?.path || 'audio')
    .replace(/\.[^.]+$/, '')
    .replace(/[^A-Za-z0-9_-]+/g, '_')
    .replace(/^_+|_+$/g, '') || 'audio';

  const fileName = `${baseName}.${detection.ext}`;

  return {
    json: {
      ...item.json,
      audio_binary_normalized: true,
      audio_binary_openai_compatible: detection.compatible,
      audio_binary_mimeType: detection.mimeType,
      audio_binary_fileName: fileName,
      audio_binary_extension: detection.ext,
      audio_binary_warning: detection.reason,
      audio_binary_magic: detection.magic,
      audio_binary_error: detection.error,
      audioText: detection.compatible
        ? item.json?.audioText
        : '[audio recebido, mas o formato interno nao e compativel para transcricao automatica]',
      media_warning: detection.compatible
        ? item.json?.media_warning ?? null
        : detection.reason || 'unsupported_audio_container',
    },
    binary: {
      ...binary,
      audio: {
        ...audio,
        mimeType: detection.mimeType,
        fileName,
        fileExtension: detection.ext,
      },
    },
  };
}));

// =============================
// DETECTA FINALIZAÇÃO — v4
// Agora detecta envio completo e confirmação de pagamento
// =============================

// 1) Pega mensagem consolidada se existir
let mensagem = $json.mensagemCliente;

// 2) Se não existir, tenta pegar do webhook (texto curto)
if (!mensagem || mensagem.trim() === "") {
  const raw = $json.body?.data?.message;

  mensagem =
    raw?.extendedTextMessage?.text ||
    raw?.conversation ||
    null;
}

// 3) Como último fallback, usa Redis2 (última mensagem)
if (!mensagem || mensagem.trim() === "") {
  const r2 = $json.Redis2;
  if (typeof r2 === "string" && r2.trim() !== "") {
    mensagem = r2;
  }
}

// 4) Se mesmo assim nada, define como vazio
mensagem = (mensagem || "").trim().toLowerCase();

// ===============
// Gatilhos de finalização de envio
// ===============
const gatilhosEnvio = [
  "pronto",
  "acabei",
  "finalizei",
  "terminei",
  "enviei tudo",
  "acho que terminei",
  "prontinho",
  "acho que foi tudo",
  "pode olhar",
  "acho que acabou",
  "concluí"
];

// ===============
// Gatilhos de pagamento confirmado
// ===============
const gatilhosPagamento = [
  "paguei",
  "efetuei o pagamento",
  "já paguei",
  "comprovante",
  "pix enviado",
  "enviei o comprovante",
  "pix feito",
  "acabei de pagar"
];

// Lista de negações (pra evitar falso positivo)
const negacoes = [
  "ainda",
  "mais",
  "vou mandar",
  "enviar mais",
  "enviando",
  "falta",
  "continuar",
  "vou pagar",
  "vou fazer o pix",
  "ainda não paguei"
];

// Função pra checar se contém negação
function contemNegacao(t) {
  return negacoes.some(n => t.includes(n));
}

// Verifica se é gatilho de envio ou pagamento
const ehEnvio = gatilhosEnvio.some(g => mensagem === g || mensagem.includes(g));
const ehPagamento = gatilhosPagamento.some(g => mensagem.includes(g));

// =============================
// OUTPUT FINAL DO NODE
// =============================

if ((ehEnvio || ehPagamento) && !contemNegacao(mensagem)) {
  return [
    {
      json: {
        finalizar: true,
        tipo: ehPagamento ? "pagamento" : "envio",
        motivo: ehPagamento
          ? "Gatilho de confirmação de pagamento detectado"
          : "Gatilho de finalização de envio detectado",
        mensagemCliente: mensagem
      }
    }
  ];
}

return [
  {
    json: {
      finalizar: false,
      motivo: "Mensagem comum",
      mensagemCliente: mensagem
    }
  }
];

