const agentOutput = String($json.output || '').trim();

const state = $('Code in JavaScript').first().json || {};
const db = $('dados do banco').first().json || {};

const conversationId = state.conversation?.id;
const tenantId = state.tenant_id || state.lead?.tenant_id;
const leadId = state.lead?.id || state.lead_id || null;
const dealId = state.deal?.id || state.deal_id || null;

if (!conversationId) throw new Error('conversation_id ausente.');
if (!tenantId) throw new Error('tenant_id ausente.');

const baseUrl =
  db.URL_SUPABASE ||
  db.SUPABASE_URL ||
  'https://dwmbklfkrtumfaxrbxio.supabase.co';

const apiKey =
  db.SUPABASE_SECRET_KEY ||
  db.SUPABASE_SERVICE_ROLE_KEY ||
  db.SUPABASE_ANON_KEY ||
  '';

if (!apiKey) throw new Error('Chave Supabase ausente para salvar outbound.');

if (agentOutput) {
  await supabaseRequest.call(this, {
    baseUrl,
    apiKey,
    method: 'POST',
    path: '/rest/v1/conversation_messages',
    body: {
      tenant_id: tenantId,
      conversation_id: conversationId,
      lead_id: leadId,
      deal_id: dealId,
      direction: 'outbound',
      sender_type: 'agent',
      content: agentOutput,
      message_type: 'text',
      external_instance: state.instance || db.instance || 'Jurema Brokers',
      external_remote_jid: state.remoteJid || null,
      metadata: {
        agent: 'ju',
        source: 'n8n'
      }
    },
    prefer: 'return=minimal'
  });

  await supabaseRequest.call(this, {
    baseUrl,
    apiKey,
    method: 'PATCH',
    path: '/rest/v1/conversations',
    qs: { id: `eq.${conversationId}` },
    body: {
      last_message: agentOutput,
      last_message_at: new Date().toISOString(),
      last_outbound_at: new Date().toISOString(),
      updated_at: new Date().toISOString()
    },
    prefer: 'return=minimal'
  });
}

return [{
  json: {
    ...$json,
    output: agentOutput,
    saved_outbound: Boolean(agentOutput),
    conversation_id: conversationId,
    lead_id: leadId,
    deal_id: dealId
  }
}];
